import type { Language } from './i18n/translate';

type Text = { en: string; pl: string };
export type HelpSection = { title: Text; paragraphs: Text[]; operations?: { name: string; description: Text }[] };
export type HelpChapter = { id: string; title: Text; sections: HelpSection[] };
const text = (en: string, pl: string): Text => ({ en, pl });

// Authored, bundled product documentation. No fetched Markdown or runtime assets.
export const helpChapters: HelpChapter[] = [
  {
    id: 'overview', title: text('1. Systems, accounts and windows', '1. Systemy, konta i okna'), sections: [
      { title: text('What the application does', 'Przeznaczenie aplikacji'), paragraphs: [
        text('System Inspector documents configured Linux systems and investigates their logs. Use Systems to open a topology, select processes, inspect retained history or explicitly start a live monitor. Diagram links describe possible data transfers; log activity and silence do not establish service health or causality.', 'System Inspector dokumentuje skonfigurowane systemy Linux i umożliwia analizę ich logów. Wybierz Systemy, otwórz topologię, zaznacz procesy i przeglądaj zachowaną historię lub jawnie uruchom monitorowanie na żywo. Połączenia na diagramie opisują możliwe przepływy danych; aktywność lub cisza w logach nie dowodzą sprawności usługi ani przyczynowości.'),
        text('One deployment and MariaDB database contain multiple Systems. A System is the Project model; project_id is its permanent technical identifier. Search, topology, imports, logs and investigations belong to the System shown in the page URL and heading.', 'Jedna instalacja i baza MariaDB zawierają wiele Systemów. System odpowiada modelowi Project; project_id jest jego trwałym identyfikatorem technicznym. Wyszukiwanie, topologia, importy, logi i analizy należą do Systemu wskazanego w adresie i nagłówku strony.'),
      ] },
      { title: text('Roles and personal preferences', 'Role i preferencje osobiste'), paragraphs: [
        text('Administrators manage Systems, topology, documentation, views, connections, parsers, imports, SSH trust, credentials, accounts and shared Settings. Inspectors navigate every configured System and investigate approved logs. Both roles own their personal investigations, notes, pins, recordings and bundle downloads. Administrator access does not grant another user’s private investigation content or target-host administration.', 'Administratorzy zarządzają Systemami, topologią, dokumentacją, widokami, połączeniami, parserami, importami, zaufaniem SSH, poświadczeniami, kontami i wspólnymi Ustawieniami. Inspektorzy przeglądają wszystkie skonfigurowane Systemy i analizują zatwierdzone logi. Obie role mają własne analizy, notatki, przypięcia, nagrania i pobrania pakietów. Rola Administratora nie udostępnia prywatnej treści analiz innego użytkownika ani administracji hostem docelowym.'),
        text('Open your account menu → Preferences for Light, Dark, System or Application default appearance and English, Polski or Application default language. These account preferences propagate across windows without resetting monitors. Remember me is an opt-in login lasting at most 30 days. Sign out all windows, password changes and account revocation end the affected account sessions across windows.', 'Otwórz menu konta → Preferencje, aby wybrać jasny, ciemny, systemowy lub domyślny wygląd oraz język English, Polski lub domyślny. Preferencje konta obowiązują we wszystkich oknach bez resetowania monitorów. Opcja Zapamiętaj mnie jest dobrowolna i utrzymuje logowanie najwyżej przez 30 dni. Wylogowanie ze wszystkich okien, zmiana hasła i unieważnienie konta kończą odpowiednie sesje konta we wszystkich oknach.'),
      ] },
      { title: text('Independent browser pages', 'Niezależne strony przeglądarki'), paragraphs: [
        text('Open separately creates another browser tab or window according to browser settings. Every page receives a fresh server workspace, even for the same account and System. Process selection, filters, time bounds, panes and live controls remain independent. Opening Help keeps the current workspace mounted. Refreshing or duplicating a page starts no SSH collection and never adopts a copied monitor automatically.', 'Otwórz osobno tworzy kolejną kartę lub okno zgodnie z ustawieniami przeglądarki. Każda strona otrzymuje nowy obszar roboczy serwera, również dla tego samego konta i Systemu. Wybór procesów, filtry, zakresy czasu, panele i sterowanie monitorami pozostają niezależne. Otwarcie Pomocy zachowuje bieżący obszar roboczy. Odświeżenie lub powielenie strony nie uruchamia zbierania przez SSH i nie przejmuje automatycznie skopiowanego monitora.'),
      ] },
    ],
  },
  {
    id: 'topology', title: text('2. Add and document elements', '2. Dodawanie i dokumentowanie elementów'), sections: [
      { title: text('System, subsystem and stable identities', 'System, podsystem i trwałe identyfikatory'), paragraphs: [
        text('An Administrator creates a System in Admin, then uses its System menu to add subsystems, servers, processes, flows, connections and parsers. Each element needs a name and a unique stable ID within that System; generated IDs can be kept. Renaming or moving an element does not change its ID. Documentation accepts safe Markdown and tags. Archiving a System retains configuration and cached investigations; active work must be handled explicitly before archival.', 'Administrator tworzy System w panelu Admin, a następnie używa jego menu System, aby dodawać podsystemy, serwery, procesy, przepływy, połączenia i parsery. Każdy element wymaga nazwy i unikalnego trwałego ID w danym Systemie; można zachować wygenerowane ID. Zmiana nazwy lub przeniesienie elementu nie zmienia ID. Dokumentacja obsługuje bezpieczny Markdown i tagi. Archiwizacja Systemu zachowuje konfigurację i analizy w pamięci podręcznej; przed archiwizacją trzeba jawnie obsłużyć aktywne zadania.'),
      ] },
      { title: text('Add server: prerequisites', 'Dodaj serwer: wymagania'), paragraphs: [
        text('Create a subsystem first: every server belongs to exactly one subsystem in its System. Use Add server in the System menu or the + button on that subsystem frame. Name, stable ID and subsystem are required. No connection is the default, so a server can appear on the map without SSH. Assign an existing profile or choose Create a new SSH profile when log access is needed.', 'Najpierw utwórz podsystem: każdy serwer należy do dokładnie jednego podsystemu w swoim Systemie. Użyj Dodaj serwer w menu System lub przycisku + na ramce podsystemu. Wymagane są nazwa, trwałe ID i podsystem. Domyślne Brak połączenia umożliwia umieszczenie serwera na mapie bez SSH. Gdy potrzebny jest dostęp do logów, przypisz istniejący profil lub wybierz Utwórz nowy profil SSH.'),
        text('An SSH profile requires a Linux hostname/IP, port (normally 22), dedicated read-account username, credential reference and absolute proposed log roots. Optionally select one existing direct jump profile. Save the profile, then set its separately stored password and verify host keys through Password & connection test. The credential reference alone is not a password. Copy opens a new profile draft with a new ID; choose a distinct name before saving.', 'Profil SSH wymaga nazwy hosta/adresu IP systemu Linux, portu (zwykle 22), nazwy dedykowanego konta odczytu, odwołania do poświadczeń i bezwzględnych proponowanych katalogów głównych logów. Opcjonalnie wybierz jeden istniejący bezpośredni profil hosta pośredniczącego. Zapisz profil, następnie ustaw osobno przechowywane hasło i zweryfikuj klucze hostów przez Hasło i test połączenia. Samo odwołanie do poświadczeń nie jest hasłem. Kopiuj otwiera szkic nowego profilu z nowym ID; przed zapisem wybierz odrębną nazwę.'),
      ] },
      { title: text('Add process: prerequisites', 'Dodaj proces: wymagania'), paragraphs: [
        text('Create a server and a parser profile in the same System first. Use Add process or the server frame’s + button. Supply a name, stable ID, server, absolute active log path, parser and encoding (UTF-8 by default). Each configured instance has one logical log source. Optional rotated patterns and ZIP/TAR.GZ archive definitions extend that source; archive definitions specify path_pattern and member_patterns. A PCS resource name is optional descriptive metadata.', 'Najpierw utwórz serwer i profil parsera w tym samym Systemie. Użyj Dodaj proces lub przycisku + na ramce serwera. Podaj nazwę, trwałe ID, serwer, bezwzględną ścieżkę aktywnego logu, parser i kodowanie (domyślnie UTF-8). Każda skonfigurowana instancja ma jedno logiczne źródło logów. Opcjonalne wzorce rotacji i definicje archiwów ZIP/TAR.GZ rozszerzają to źródło; definicje archiwów określają path_pattern i member_patterns. Nazwa zasobu PCS jest opcjonalną informacją opisową.'),
        text('The proposed path is app.log below the first log root of the server’s connection; without a root it starts empty. Changing the server updates only an unedited proposal. Typed paths are preserved. All active, rotated and archive paths must stay below the assigned profile’s roots. A documented server without a connection can contain processes, but remote collection is rejected until a usable connection is assigned. Current remote collection rejects symlink paths; use real regular-file paths.', 'Proponowana ścieżka to app.log w pierwszym katalogu logów połączenia serwera; bez katalogu pole pozostaje puste. Zmiana serwera aktualizuje tylko nieedytowaną propozycję. Wpisane ścieżki są zachowywane. Wszystkie ścieżki aktywne, rotowane i archiwalne muszą mieścić się w katalogach przypisanego profilu. Udokumentowany serwer bez połączenia może zawierać procesy, ale zdalne zbieranie jest odrzucane do czasu przypisania działającego połączenia. Bieżący odczyt zdalny odrzuca ścieżki z dowiązaniami symbolicznymi; użyj rzeczywistych ścieżek zwykłych plików.'),
        text('Parsers support an ISO 8601 prefix or configured fixed-width UTC timestamp and optional correlation markers. Test parser sample previews timestamps, exact microseconds, metadata and errors without saving the draft. A sample is limited to 64 KiB UTF-8, 100 physical lines and 4 KiB per line. A failed timestamp remains a diagnostic event.', 'Parsery obsługują prefiks ISO 8601 lub skonfigurowany znacznik czasu UTC o stałej szerokości oraz opcjonalne znaczniki korelacji. Test próbki parsera pokazuje czas, dokładne mikrosekundy, metadane i błędy bez zapisywania szkicu. Próbka ma limit 64 KiB UTF-8, 100 fizycznych wierszy i 4 KiB na wiersz. Niepoprawny znacznik czasu pozostaje zdarzeniem diagnostycznym.'),
      ] },
      { title: text('Views, movement and flows', 'Widoki, przenoszenie i przepływy'), paragraphs: [
        text('Select elements to read documentation; search reveals matching elements and their parents. Pan, zoom, select, collapse groups and inspect dependencies. Administrators edit shared geometry on an invisible 8-pixel grid, use explicit Move to server/subsystem for parent changes, and save named views referencing existing entities. Undo/Redo and delete-impact review protect shared edits. Revision conflicts require reloading current configuration before retrying. A directed flow requires source and target processes and describes a possible transfer.', 'Zaznacz element, aby odczytać dokumentację; wyszukiwanie ujawnia pasujące elementy i ich rodziców. Przesuwaj widok, zmieniaj powiększenie, zaznaczaj, zwijaj grupy i badaj zależności. Administratorzy edytują wspólną geometrię na niewidocznej siatce 8 pikseli, jawnie zmieniają rodzica przez Przenieś do serwera/podsystemu i zapisują nazwane widoki istniejących elementów. Cofnij/Ponów i przegląd skutków usunięcia chronią wspólne zmiany. Konflikt wersji wymaga odczytania bieżącej konfiguracji przed ponowieniem. Skierowany przepływ wymaga procesu źródłowego i docelowego i opisuje możliwy transfer.'),
      ] },
    ],
  },
  {
    id: 'ssh', title: text('3. SSH access and exact remote operations', '3. Dostęp SSH i dokładne operacje zdalne'), sections: [
      { title: text('Prepare and approve access', 'Przygotowanie i zatwierdzenie dostępu'), paragraphs: [
        text('The application server must resolve and reach the configured host over LAN/VPN; browser connectivity alone is insufficient. The target must provide SSH password authentication and the SFTP subsystem. The dedicated account needs directory traversal and read permissions for active logs, future rotations and archives, without sudo. A jump account needs permission to forward to the approved target. Provision these permissions outside this application.', 'Serwer aplikacji musi rozwiązywać nazwę i osiągać skonfigurowany host przez LAN/VPN; samo połączenie z przeglądarki nie wystarcza. Host docelowy musi udostępniać uwierzytelnianie SSH hasłem i podsystem SFTP. Dedykowane konto wymaga przechodzenia po katalogach i odczytu aktywnych logów, przyszłych rotacji i archiwów, bez sudo. Konto hosta pośredniczącego wymaga prawa przekazywania połączenia do zatwierdzonego celu. Uprawnienia te nadaje się poza aplikacją.'),
        text('An Administrator binds the credential to this System, inspects target and jump fingerprints, compares each with an independent trusted source, then explicitly approves the keys. Unknown or changed keys block authentication. Inspection alone grants no trust. With Additional security measures enabled (the default), confirm the current source/target/root revision and expiry before collection. Disabling that extra confirmation never bypasses credentials, host-key checks, destination/root validation or access limits. Saving or importing configuration starts no SSH operation.', 'Administrator wiąże poświadczenie z danym Systemem, odczytuje odciski kluczy celu i hosta pośredniczącego, porównuje każdy z niezależnym zaufanym źródłem, a następnie jawnie zatwierdza klucze. Nieznane lub zmienione klucze blokują uwierzytelnienie. Sam odczyt nie ustanawia zaufania. Przy włączonych Dodatkowych zabezpieczeniach (domyślnie) przed zbieraniem zatwierdź bieżącą wersję źródła/celu/katalogów i termin ważności. Wyłączenie dodatkowego potwierdzenia nie pomija poświadczeń, kluczy hostów, kontroli celu/katalogów ani limitów. Zapis lub import konfiguracji nie uruchamia operacji SSH.'),
      ] },
      { title: text('Complete remote command list: none', 'Pełna lista poleceń zdalnych: brak'), paragraphs: [
        text('The SSH module sends zero remote shell commands. It opens no terminal and does not invoke tail, grep, cat, find, ls, stat, journalctl, systemctl, pcs, sudo or archive utilities. Process definitions describe logs; they never start, stop or manage operating-system processes. Filters and correlation terms are evaluated by the backend over retained data and are never interpolated into a shell.', 'Moduł SSH nie wysyła żadnych zdalnych poleceń powłoki. Nie otwiera terminala i nie wywołuje tail, grep, cat, find, ls, stat, journalctl, systemctl, pcs, sudo ani narzędzi archiwizujących. Definicje procesów opisują logi; nigdy nie uruchamiają, nie zatrzymują ani nie zarządzają procesami systemu operacyjnego. Filtry i terminy korelacji oblicza backend na zachowanych danych; nie są wstawiane do powłoki.'),
        text('The complete application-requested remote operation set is below. These are SSH/SFTP protocol operations, not command-line programs. SSH negotiation also exchanges protocol version, algorithms and keepalives. Archives are read as bytes and validated/decoded on the application server.', 'Poniżej znajduje się pełny zestaw zdalnych operacji żądanych przez aplikację. Są to operacje protokołów SSH/SFTP, a nie programy wiersza poleceń. Negocjacja SSH wymienia także wersję protokołu, algorytmy i komunikaty podtrzymania. Archiwa są odczytywane jako bajty, a następnie walidowane i dekodowane na serwerze aplikacji.'),
      ], operations: [
        { name: 'SSH host-key handshake', description: text('Inspect a proposed fingerprint without target authentication; the inspection callback rejects the target key. A configured jump already requires trusted authentication.', 'Odczyt proponowanego odcisku bez uwierzytelnienia do celu; funkcja kontroli odrzuca klucz celu. Skonfigurowany host pośredniczący wymaga już zaufanego uwierzytelnienia.') },
        { name: 'SSH password authentication', description: text('Authenticate the configured log-read account only after the pinned host key matches. No agent forwarding or client-key authentication.', 'Uwierzytelnienie skonfigurowanego konta odczytu dopiero po dopasowaniu zatwierdzonego klucza. Bez przekazywania agenta i uwierzytelniania kluczem klienta.') },
        { name: 'SSH direct-tcpip (optional)', description: text('One internal jump channel to the configured target SSH endpoint; target and jump use separate key/credential checks.', 'Jeden wewnętrzny kanał przez host pośredniczący do skonfigurowanego punktu SSH; cel i host pośredniczący mają oddzielne kontrole kluczy i poświadczeń.') },
        { name: 'SSH subsystem: sftp / SFTP INIT', description: text('Negotiate SFTP for a connection test or a requested read operation; no SSH exec request.', 'Negocjacja SFTP do testu połączenia lub żądanego odczytu; bez żądania SSH exec.') },
        { name: 'SFTP LSTAT · lstat(path)', description: text('Inspect each path component and reject symlinks, unexpected types and inaccessible paths.', 'Kontrola każdego składnika ścieżki oraz odrzucenie dowiązań, nieoczekiwanych typów i niedostępnych ścieżek.') },
        { name: 'SFTP REALPATH · realpath(path)', description: text('Check the canonical path against the configured root before reading.', 'Sprawdzenie ścieżki kanonicznej względem skonfigurowanego katalogu przed odczytem.') },
        { name: 'SFTP OPENDIR / READDIR / CLOSE · scandir(directory)', description: text('List bounded candidate directory entries for configured rotation/archive patterns; close the directory handle.', 'Odczyt ograniczonej listy kandydatów we wskazanym katalogu dla wzorców rotacji/archiwów; zamknięcie uchwytu katalogu.') },
        { name: 'SFTP OPEN · open(path, FXF_READ)', description: text('Open a validated regular file read-only, with one bounded request at a time.', 'Otwarcie zweryfikowanego zwykłego pliku tylko do odczytu, z jednym ograniczonym żądaniem naraz.') },
        { name: 'SFTP FSTAT · handle.stat()', description: text('Check the opened file’s size/type/metadata and compare snapshots for changes.', 'Kontrola rozmiaru/typu/metadanych otwartego pliku i porównanie migawek pod kątem zmian.') },
        { name: 'SFTP READ · handle.read(length, offset)', description: text('Read bounded byte ranges for source probes, history, recent matching history and appended live content.', 'Odczyt ograniczonych zakresów bajtów do kontroli źródła, historii, najnowszej pasującej historii i dopisanej treści na żywo.') },
        { name: 'SFTP CLOSE / SSH channel close', description: text('Close read handles and SFTP/SSH channels; abort stalled or cancelled reads within bounded cleanup.', 'Zamknięcie uchwytów odczytu i kanałów SFTP/SSH; przerwanie zawieszonych lub anulowanych odczytów w ograniczonym czasie.') },
      ] },
    ],
  },
  {
    id: 'history', title: text('4. Historical collection and filters', '4. Historia i filtry'), sections: [
      { title: text('Collect and inspect', 'Zbieranie i przeglądanie'), paragraphs: [
        text('Select one or more processes, choose Inspect history, set Collection time range in UTC and explicitly start collection. Preview candidate sources and estimated budgets when needed; direct collection enforces the same checks. Plain logs, configured rotations and regular ZIP/TAR.GZ members are read into bounded private server cache. A failed source remains visible while successful source results remain available. Cancel interrupts collection and retains clearly labelled partial coverage.', 'Zaznacz jeden lub kilka procesów, wybierz analizę historii, ustaw Zakres czasu zbierania w UTC i jawnie rozpocznij zbieranie. W razie potrzeby wyświetl kandydatów źródeł i szacowane limity; bezpośrednie zbieranie stosuje te same kontrole. Zwykłe logi, skonfigurowane rotacje i zwykłe pliki z ZIP/TAR.GZ trafiają do ograniczonej prywatnej pamięci podręcznej serwera. Błędne źródło pozostaje widoczne, a wyniki poprawnych źródeł pozostają dostępne. Anulowanie przerywa zbieranie i zachowuje wyraźnie oznaczone częściowe pokrycie.'),
        text('Times are event timestamps in UTC with [from, to) bounds: From is included, To is excluded. Display uses YYYY-MM-DD HH:mm:ss; exact stored microseconds and original text remain available in provenance. One physical line is one event. Unknown or invalid timestamps stay in a diagnostic lane, without invented times. Equal text at different byte positions represents distinct events.', 'Czas oznacza znaczniki zdarzeń w UTC z granicami [od, do): Od jest włączone, Do wyłączone. Wyświetlany format to YYYY-MM-DD HH:mm:ss; dokładne zapisane mikrosekundy i oryginalna treść pozostają w danych pochodzenia. Jeden fizyczny wiersz to jedno zdarzenie. Nieznane lub błędne znaczniki czasu pozostają w panelu diagnostycznym bez wymyślonego czasu. Identyczny tekst w różnych pozycjach bajtowych oznacza odrębne zdarzenia.'),
      ] },
      { title: text('Display retained data', 'Wyświetlanie zachowanych danych'), paragraphs: [
        text('Filters changes the display range and literal include/exclude terms over the opened collection; it does not change the next collection’s time range or reconnect SSH. Choose any/all inclusion, case sensitivity and optional per-process rules. Case-insensitive matching uses Unicode casefold. Each scope supports at most 20 include and 20 exclude terms of 512 Unicode characters each. Terms are literal strings, including punctuation and embedded newlines.', 'Filtry zmieniają wyświetlany zakres i dosłowne warunki uwzględniania/wykluczania otwartej kolekcji; nie zmieniają czasu następnego zbierania ani nie łączą ponownie SSH. Wybierz dowolny/wszystkie warunki, rozróżnianie wielkości liter i opcjonalne reguły dla procesów. Dopasowanie bez rozróżniania liter używa Unicode casefold. Każdy zakres obsługuje najwyżej 20 warunków uwzględniania i 20 wykluczania po 512 znaków Unicode. Warunki są dosłowne, również ze znakami specjalnymi i nowymi wierszami.'),
        text('Choose merged results or separate process panes, Show process, Columns, Rows/Viewport and Full screen. These controls affect this page’s presentation. The context eye opens original source-order lines, including nonmatching neighbours; out-of-range context is labelled separately. Coverage, parse errors, byte/line provenance and scan warnings explain completeness. No matches does not mean no available data.', 'Wybierz wyniki scalone lub osobne panele procesów, Pokaż proces, Kolumny, Wiersze/Obszar widoczny i Pełny ekran. Te opcje dotyczą prezentacji na tej stronie. Oko kontekstu otwiera oryginalne wiersze w kolejności źródła, również niepasujących sąsiadów; kontekst poza zakresem jest oznaczony oddzielnie. Pokrycie, błędy parsowania, pozycje bajtów/wierszy i ostrzeżenia skanowania objaśniają kompletność. Brak dopasowań nie oznacza braku danych.'),
      ] },
    ],
  },
  {
    id: 'live', title: text('5. Live monitoring and continuity', '5. Monitorowanie na żywo i ciągłość'), sections: [
      { title: text('Start, filter, pause and stop', 'Uruchamianie, filtrowanie, pauza i zatrzymanie'), paragraphs: [
        text('Select processes and choose Monitor or Monitor selected, then explicitly start this page’s monitor. Initial history seeks enough matching lines for the measured viewport, subject to scan-byte, line and time limits. Load older requests more retained/backfill history within those limits. Changing filters re-evaluates retained unfiltered events without reconnecting SSH; it cannot recover data already evicted from the buffer.', 'Zaznacz procesy, wybierz Monitoruj lub Monitoruj zaznaczone, a następnie jawnie uruchom monitor tej strony. Początkowa historia szuka tylu pasujących wierszy, ile mieści widoczny obszar, z limitami bajtów, wierszy i czasu. Wczytaj starsze żąda dalszej zachowanej/uzupełnianej historii w tych granicach. Zmiana filtrów ponownie ocenia zachowane niefiltrowane zdarzenia bez ponownego łączenia SSH; nie odzyskuje danych usuniętych z bufora.'),
        text('Pause display freezes presentation while server collection continues. Resume catches up to retained data. Stop this monitor ends its capture only after the server acknowledges it. A disconnected WebSocket is a connection problem, not an acknowledged stop. Background/minimized pages keep collecting. Default detached reconnect grace is 300 seconds; refresh requires explicit Resume in this window for an eligible detached monitor. Occupied control leases cannot be silently taken over.', 'Wstrzymaj wyświetlanie zamraża prezentację, ale serwer nadal zbiera dane. Wznów przechodzi do zachowanych danych. Zatrzymaj ten monitor kończy jego zbieranie dopiero po potwierdzeniu serwera. Rozłączony WebSocket to problem połączenia, a nie potwierdzone zatrzymanie. Strony w tle lub zminimalizowane nadal zbierają dane. Domyślny czas ponownego połączenia po odłączeniu wynosi 300 sekund; po odświeżeniu trzeba jawnie wybrać Wznów w tym oknie dla kwalifikującego się monitora. Nie można po cichu przejąć zajętego sterowania.'),
      ] },
      { title: text('Limits, gaps and recording', 'Limity, luki i nagrywanie'), paragraphs: [
        text('Counters distinguish received, matching, rendered, filtered and evicted events. Rotation, truncation, reconnects, slow clients and bounded buffers can produce gaps or uncertain continuity; read the visible coverage warnings. Exactly-once capture across all file changes is not guaranteed. Silence is not proof that a process stopped. Enable explicit recording to retain live events as an investigation instead of relying on a transient buffer.', 'Liczniki rozróżniają zdarzenia odebrane, pasujące, wyświetlone, odfiltrowane i usunięte z bufora. Rotacja, obcięcie, ponowne połączenia, powolni klienci i ograniczone bufory mogą powodować luki lub niepewną ciągłość; czytaj widoczne ostrzeżenia o pokryciu. Nie ma gwarancji przechwycenia dokładnie raz przy wszystkich zmianach plików. Cisza nie dowodzi zatrzymania procesu. Włącz jawne nagrywanie, aby zachować zdarzenia jako analizę zamiast polegać na buforze tymczasowym.'),
        text('Nominal live ceilings are 5 process subscriptions per workspace and 10 per System, account and deployment. Workspaces default to 8 per account and 64 globally; history jobs to 2 per account/System and 4 globally. Existing lower deployment limits apply. Limits count subscriptions across your windows; a rejected start must leave established monitors running. A second System needs no second backend or database.', 'Nominalne limity wynoszą 5 subskrypcji procesów na obszar roboczy i 10 na System, konto i instalację. Domyślnie dostępnych jest 8 obszarów na konto i 64 łącznie; zadań historii 2 na konto/System i 4 łącznie. Obowiązują istniejące niższe limity instalacji. Subskrypcje z różnych okien sumują się; odrzucony start pozostawia działające monitory. Drugi System nie wymaga drugiego backendu ani bazy.'),
      ] },
    ],
  },
  {
    id: 'investigations', title: text('6. Save, pin, correlate and exchange', '6. Zapis, przypięcia, korelacja i wymiana'), sections: [
      { title: text('Personal analysis and retention', 'Analiza osobista i retencja'), paragraphs: [
        text('Save a named investigation with process selection, UTC bounds, filters, layout and collection references. Reopen it against retained data even when target hosts are disconnected. Notes and bookmarks are personal; they do not modify source logs. A source-context bookmark can retain explicitly pinned context. Expired unpinned source data is reported as unavailable rather than complete.', 'Zapisz nazwaną analizę z wyborem procesów, granicami UTC, filtrami, układem i odwołaniami do kolekcji. Otwieraj ją na zachowanych danych także po odłączeniu hostów docelowych. Notatki i zakładki są osobiste; nie zmieniają logów źródłowych. Zakładka kontekstu może zachować jawnie przypięty kontekst. Wygasłe nieprzypięte źródło jest oznaczane jako niedostępne, a nie kompletne.'),
        text('Mark 1–100 event rows by clicking or using Space/Enter, then Pin to save one described group with original text and provenance. View opens grouped process text; Save edits the description, Modify restores row selection for updating or creating a new group, and Delete pin removes the group. Grouped pins retain their saved text after source-cache expiry. Deleting a finished collection requires confirmation and removes its retained source data; active work must finish or be cancelled first.', 'Zaznacz 1–100 wierszy kliknięciem lub klawiszami Spacja/Enter, a następnie Przypnij, aby zapisać jedną opisaną grupę z oryginalną treścią i pochodzeniem. Wyświetl otwiera tekst pogrupowany według procesu; Zapisz zmienia opis, Modyfikuj przywraca zaznaczenie do aktualizacji lub nowej grupy, a Usuń przypięcie usuwa grupę. Grupy zachowują zapisany tekst po wygaśnięciu źródła w pamięci podręcznej. Usunięcie zakończonej kolekcji wymaga potwierdzenia i usuwa zachowane źródła; aktywne zadanie musi się skończyć lub zostać anulowane.'),
      ] },
      { title: text('Correlation and offline bundles', 'Korelacja i pakiety offline'), paragraphs: [
        text('Use a configured correlation marker or selected identifier to trace matching retained events across the chosen processes. Chronological deltas are observed event-time differences; they do not prove transport latency or causality. Add dependency neighbours explicitly when expanding the investigation.', 'Użyj skonfigurowanego znacznika korelacji lub wybranego identyfikatora, aby śledzić pasujące zachowane zdarzenia w wybranych procesach. Różnice czasu są obserwowanymi różnicami znaczników zdarzeń; nie dowodzą opóźnienia transmisji ani przyczynowości. Jawnie dodaj sąsiadów zależności przy rozszerzaniu analizy.'),
        text('Preview redaction before exporting your investigation bundle. It can contain selected logs, notes/pins, topology snapshot, provenance, version metadata and checksums; it excludes SSH passwords, credential ciphertext, active connection details and trust. Review remaining sensitive text manually: redaction is not a guarantee of anonymisation. Import validates members and checksums and creates your own offline copy in the selected System, without replacing topology or starting SSH. This is the explicit exchange path between users.', 'Przed eksportem pakietu analizy przejrzyj anonimizację. Pakiet może zawierać wybrane logi, notatki/przypięcia, migawkę topologii, pochodzenie, wersje i sumy kontrolne; nie zawiera haseł SSH, zaszyfrowanych poświadczeń, aktywnych szczegółów połączeń ani zaufania. Ręcznie sprawdź pozostałą wrażliwą treść: redakcja nie gwarantuje anonimizacji. Import sprawdza elementy i sumy kontrolne oraz tworzy własną kopię offline w wybranym Systemie bez zastępowania topologii i uruchamiania SSH. To jawna droga wymiany między użytkownikami.'),
      ] },
    ],
  },
  {
    id: 'imports', title: text('7. Configuration and inventory imports', '7. Import konfiguracji i inwentarza'), sections: [
      { title: text('Versioned configuration', 'Wersjonowana konfiguracja'), paragraphs: [
        text('Administrators export/import single-System YAML or JSON schema 2.0 through an explicit preview and commit; older v1 input has previewed conversion. Confirm the target System and expected revision. MariaDB remains the runtime source of truth: exported files are interchange snapshots, not a second live configuration writer. Secret values are never exported. Imported connections still need separate credentials and host-key trust.', 'Administratorzy eksportują/importują YAML lub JSON jednego Systemu w schemacie 2.0 przez jawny podgląd i zatwierdzenie; starsze dane v1 mają konwersję z podglądem. Sprawdź System docelowy i oczekiwaną wersję. MariaDB pozostaje źródłem prawdy w czasie działania: eksportowane pliki są migawkami wymiany, a nie drugim aktywnym źródłem konfiguracji. Wartości sekretów nie są eksportowane. Importowane połączenia nadal wymagają oddzielnych poświadczeń i zaufania kluczom.'),
      ] },
      { title: text('Single server JSON', 'JSON pojedynczego serwera'), paragraphs: [
        text('Choose System → Import server JSON to add one host and its services to the selected System. Download the complete example for your export script. Use format system-inspector-server and schema_version 1.0, one server object and a services list. Each service is a configured process with one file log source, including any rotations and archives. Supply an existing parser ID or map it in the wizard. An empty services list imports only the server.', 'Wybierz System → Importuj serwer z JSON, aby dodać jeden host i jego usługi do wybranego Systemu. Pobierz kompletny przykład dla swojego skryptu eksportującego. Użyj format system-inspector-server i schema_version 1.0, jednego obiektu server oraz listy services. Każda usługa to skonfigurowany proces z jednym plikowym źródłem logów, obejmującym rotacje i archiwa. Podaj istniejący identyfikator parsera lub przypisz go w kreatorze. Pusta lista services importuje sam serwer.'),
        text('Keep server.id and each service id unchanged when renaming or changing addresses; the name fields are display labels. Select the same inventory source on repeat imports, review the proposed changes and explicitly commit. Other servers, omitted services, documentation and layouts are retained; manual edits to imported fields require conflict resolution. JSON never supplies passwords, host-key trust or target approval and import starts no SSH connection.', 'Zachowaj server.id oraz identyfikatory usług przy zmianie nazw lub adresów; pola name są nazwami wyświetlanymi. Przy ponownym imporcie wybierz to samo źródło inwentarza, przejrzyj proponowane zmiany i jawnie je zatwierdź. Pozostałe serwery, pominięte usługi, dokumentacja i układy zostają zachowane; ręczne zmiany importowanych pól wymagają rozwiązania konfliktów. JSON nie dostarcza haseł, zaufania kluczom ani zatwierdzenia hosta, a import nie uruchamia połączenia SSH.'),
      ] },
      { title: text('Static Ansible setup wizard', 'Kreator statycznego inwentarza Ansible'), paragraphs: [
        text('Choose Import Ansible inventory files in the selected System. Select/create a stable inventory source, upload static INI (including extensionless hosts), YAML/YML, canonical JSON or a ZIP with uploaded relative group_vars/host_vars. For ZIP select source files in explicit order, parse, map hosts/groups to exactly one subsystem per host, map existing project credentials/jump/parsers where needed, review changes, then commit. A host-only inventory creates no processes.', 'Wybierz Importuj pliki inwentarza Ansible w wybranym Systemie. Wybierz/utwórz trwałe źródło inwentarza, prześlij statyczny INI (także hosts bez rozszerzenia), YAML/YML, kanoniczny JSON lub ZIP z przesłanymi względnymi group_vars/host_vars. Dla ZIP wybierz kolejność źródeł, parsuj, przypisz hosty/grupy do dokładnie jednego podsystemu na host, w razie potrzeby wskaż istniejące poświadczenia/hosty pośredniczące/parsery projektu, przejrzyj zmiany i zatwierdź. Inwentarz samych hostów nie tworzy procesów.'),
        text('Reimport identity includes System, inventory source, host alias and optional local process ID. Unchanged input preserves IDs and revision; missing hosts/processes remain present. Documentation, geometry, flows and unrelated processes are preserved. Manual managed-field edits or stale previews block commit for review. Uploads expire after 15 minutes and are removed on commit/cancel/expiry. Nominal bounds are 10 MiB upload, 20 MiB expanded data and 200 entries; lower configured limits apply.', 'Tożsamość ponownego importu obejmuje System, źródło inwentarza, alias hosta i opcjonalne lokalne ID procesu. Niezmienione dane zachowują ID i wersję; brakujące hosty/procesy pozostają. Dokumentacja, geometria, przepływy i niezwiązane procesy są zachowywane. Ręczne zmiany pól zarządzanych lub nieaktualny podgląd blokują zatwierdzenie do przeglądu. Pliki wygasają po 15 minutach i są usuwane po zatwierdzeniu/anulowaniu/wygaśnięciu. Nominalne granice to 10 MiB przesyłu, 20 MiB rozwiniętych danych i 200 elementów; obowiązują niższe limity konfiguracji.'),
        text('The importer never executes Ansible, scripts, plugins, playbooks, Jinja, lookups, ProxyCommand or uploaded ansible.cfg and never reads unuploaded companion files. Unsafe ZIP paths/links, YAML tags/anchors, Vault, cycles, unsupported ranges and ambiguous variable semantics produce diagnostics. Complex trusted inventories can be resolved externally to canonical JSON before upload; no Ansible runtime is installed or required by this application.', 'Importer nigdy nie uruchamia Ansible, skryptów, wtyczek, playbooków, Jinja, lookup, ProxyCommand ani przesłanego ansible.cfg i nie czyta nieprzesłanych plików towarzyszących. Niebezpieczne ścieżki/dowiązania ZIP, tagi/kotwice YAML, Vault, cykle, nieobsługiwane zakresy i niejednoznaczne zmienne powodują diagnostykę. Złożony zaufany inwentarz można zewnętrznie przekształcić do kanonicznego JSON przed przesłaniem; aplikacja nie instaluje ani nie wymaga środowiska Ansible.'),
      ] },
    ],
  },
  {
    id: 'operations', title: text('8. Backend, database, files and operations', '8. Backend, baza, pliki i utrzymanie'), sections: [
      { title: text('Deployment architecture and prerequisites', 'Architektura i wymagania instalacji'), paragraphs: [
        text('A Linux server runs one FastAPI/Python ASGI worker, bounded background workers, MariaDB and an HTTPS reverse proxy. React/TypeScript/Vite, React Flow and TanStack Virtual assets are built and bundled locally; Windows 10/11 browsers are clients. Runtime requires no Internet, CDN, AI API, telemetry or update service. The server still needs authorised LAN/VPN/DNS access for requested SSH reads. Internal certificates must be provisioned and trusted by clients; no online certificate enrollment is required.', 'Serwer Linux uruchamia jeden proces ASGI FastAPI/Python, ograniczoną pulę zadań, MariaDB i odwrotne proxy HTTPS. Zasoby React/TypeScript/Vite, React Flow i TanStack Virtual są budowane i pakowane lokalnie; przeglądarki Windows 10/11 są klientami. Działanie nie wymaga Internetu, CDN, API AI, telemetrii ani usługi aktualizacji. Serwer nadal wymaga zatwierdzonego dostępu LAN/VPN/DNS do żądanych odczytów SSH. Certyfikaty wewnętrzne trzeba dostarczyć i zaufać im na klientach; internetowe wystawianie certyfikatów nie jest wymagane.'),
        text('Release recipes target Ubuntu LTS with Docker Compose and Rocky Linux 9 with Podman/systemd. An approved container runtime, Linux facilities, storage permissions and trusted certificates must already be available offline. Consult the release test report for platforms actually tested; a supplied recipe alone does not certify that operating system. No installation or upgrade is triggered by opening this Help.', 'Przepisy wydania są przeznaczone dla Ubuntu LTS z Docker Compose i Rocky Linux 9 z Podman/systemd. Zatwierdzone środowisko kontenerowe, składniki Linux, uprawnienia do magazynu i zaufane certyfikaty muszą być dostępne offline. Sprawdź w raporcie wydania faktycznie przetestowane platformy; sam przepis nie potwierdza systemu operacyjnego. Otwarcie Pomocy nie uruchamia instalacji ani aktualizacji.'),
      ] },
      { title: text('Configuration files and persistent state', 'Pliki konfiguracji i trwały stan'), paragraphs: [
        text('The backend reads INSPECTOR_CONFIG_FILE, default /etc/system-inspector/application.yaml. Deployment policy schema 2.0 specifies public_origin, private state_dir/cache_dir, vault_key_file, one ASGI worker, database endpoint/TLS/pool/timeouts, resource limits, retention and authentication policy. Repository examples are examples/deployment-policy.example.yaml and examples/application.external-db.example.yaml. Deployment changes are server-operator work requiring validation and restart; selecting a System never changes the database endpoint.', 'Backend odczytuje INSPECTOR_CONFIG_FILE, domyślnie /etc/system-inspector/application.yaml. Polityka instalacji w schemacie 2.0 określa public_origin, prywatne state_dir/cache_dir, vault_key_file, jeden proces ASGI, punkt bazy/TLS/pulę/limity czasu, limity zasobów, retencję i uwierzytelnianie. Przykłady w repozytorium to examples/deployment-policy.example.yaml i examples/application.external-db.example.yaml. Zmiany instalacji wykonuje operator serwera z walidacją i restartem; wybór Systemu nigdy nie zmienia punktu bazy.'),
        text('MariaDB stores topology/revisions, accounts/roles/preferences, sessions, source/trust metadata, jobs, events/provenance, personal analysis, import mappings and audits. Explicit host, port, database name, username and password file are required. External endpoints require certificate and hostname verification. The serving account has scoped data privileges; separate migration credentials are used only by the migration tool, and database root credentials only for provisioning/recovery. There is no SQLite fallback.', 'MariaDB przechowuje topologię/wersje, konta/role/preferencje, sesje, metadane źródeł/zaufania, zadania, zdarzenia/pochodzenie, analizy osobiste, mapowania importu i audyt. Wymagane są jawny host, port, nazwa bazy, użytkownik i plik hasła. Zewnętrzne punkty wymagają weryfikacji certyfikatu i nazwy hosta. Konto serwujące ma ograniczone prawa do danych; oddzielne poświadczenia migracji otrzymuje tylko narzędzie migracyjne, a root bazy służy wyłącznie inicjalizacji/odtwarzaniu. Nie ma awaryjnej bazy SQLite.'),
        text('Raw log/cache files are private server storage scoped to their System and authorised investigation; they are never static web assets. Default cache policy is 14 days/10 GiB, subject to saved policy. SSH passwords are separately encrypted with a protected mounted vault key. Raw cache is not automatically encrypted; encrypted host storage is an operator option. Keep secret files, TLS keys and vault recovery material outside exports and images.', 'Surowe logi/pamięć podręczna to prywatny magazyn serwera przypisany do Systemu i uprawnionej analizy; nigdy nie są statycznymi zasobami WWW. Domyślna polityka pamięci wynosi 14 dni/10 GiB, zgodnie z zapisaną konfiguracją. Hasła SSH są osobno szyfrowane chronionym zamontowanym kluczem sejfu. Surowa pamięć podręczna nie jest automatycznie szyfrowana; szyfrowanie magazynu hosta jest opcją operatora. Pliki sekretów, klucze TLS i materiał odzyskiwania sejfu przechowuj poza eksportami i obrazami.'),
      ] },
      { title: text('Application logs, audit and diagnostics', 'Logi aplikacji, audyt i diagnostyka'), paragraphs: [
        text('Operational application/proxy/container logs are distinct from investigated target log events. Use the deployed runtime’s service logs and Administrator diagnostics to inspect readiness, schema, safe errors and job counts. Security/configuration operations are audited using IDs, counts and outcomes; audit is not tamper-proof. Do not paste credentials or raw source logs into support output. Passwords, tokens, credential ciphertext, raw source text and filter/correlation values must not enter ordinary application logs.', 'Logi operacyjne aplikacji/proxy/kontenerów są odrębne od analizowanych zdarzeń hostów docelowych. Użyj logów usług wdrożonego środowiska i diagnostyki Administratora do sprawdzenia gotowości, schematu, bezpiecznych błędów i liczby zadań. Operacje bezpieczeństwa/konfiguracji są audytowane przez ID, liczniki i wyniki; audyt nie jest odporny na manipulację. Nie wklejaj poświadczeń ani surowych logów źródłowych do zgłoszeń. Hasła, tokeny, zaszyfrowane poświadczenia, surowa treść i wartości filtrów/korelacji nie mogą trafiać do zwykłych logów aplikacji.'),
      ] },
      { title: text('Backup, restore and upgrade', 'Kopia zapasowa, odtwarzanie i aktualizacja'), paragraphs: [
        text('Follow the operator guide packaged with the exact release. Stop/quiesce serving, collection, edits and retention; take a consistent MariaDB backup coordinated with all Systems’ cache/manifests and protected configuration. Preserve roles, preferences, ownership and pinned content. Back up the vault key separately under restricted access: a database backup alone cannot decrypt stored SSH passwords. Never copy a running database datadir as a substitute for a consistent backup.', 'Postępuj według instrukcji operatora dołączonej do danego wydania. Zatrzymaj/wycisz serwowanie, zbieranie, edycję i retencję; wykonaj spójną kopię MariaDB razem z pamięcią/manifestami wszystkich Systemów i chronioną konfiguracją. Zachowaj role, preferencje, właścicieli i przypiętą treść. Klucz sejfu kopiuj oddzielnie z ograniczonym dostępem: sama kopia bazy nie odszyfruje haseł SSH. Nie zastępuj spójnej kopii kopiowaniem katalogu działającej bazy.'),
        text('Verify artifact/backup checksums and test restore in an isolated location, including disconnected investigations. Apply migrations explicitly with serving stopped and separate migration credentials. Keep the previous image and its matching pre-migration backup for rollback; old code cannot safely serve an incompatible new schema. Revoke restored web sessions before exposing restored service. Startup marks interrupted work and does not automatically reconnect target SSH; resume collection explicitly.', 'Sprawdź sumy kontrolne artefaktów/kopii i przetestuj odtworzenie w izolowanym miejscu, także analiz bez połączenia z hostami. Migracje wykonuj jawnie przy zatrzymanym serwowaniu i oddzielnych poświadczeniach migracji. Zachowaj poprzedni obraz i zgodną kopię sprzed migracji do wycofania; stary kod nie może bezpiecznie obsługiwać niezgodnego nowego schematu. Unieważnij odtworzone sesje WWW przed udostępnieniem usługi. Start oznacza przerwane zadania i nie łączy ponownie SSH automatycznie; zbieranie wznów jawnie.'),
      ] },
    ],
  },
  {
    id: 'security', title: text('9. Security, limits and troubleshooting', '9. Bezpieczeństwo, limity i rozwiązywanie problemów'), sections: [
      { title: text('Trust boundaries and bounded work', 'Granice zaufania i ograniczona praca'), paragraphs: [
        text('Authentication, roles, ownership, System scope and live workspace leases are checked by the backend for HTTP, WebSockets and downloads. HTTPS, strict cookies, CSRF and origin checks protect requests. Logs render as text; Markdown disables remote assets and raw HTML. Uploaded archives and inventories are data, never executable instructions. Only validated regular archive members are streamed; traversal, links and unsafe types are rejected without general extraction.', 'Backend sprawdza uwierzytelnienie, role, właściciela, zakres Systemu i sterowanie obszarem roboczym dla HTTP, WebSocketów i pobrań. HTTPS, ścisłe ciasteczka, CSRF i kontrola pochodzenia chronią żądania. Logi są tekstem; Markdown wyłącza zdalne zasoby i surowy HTML. Archiwa i inwentarze są danymi, nigdy instrukcjami wykonywalnymi. Strumieniowane są tylko zweryfikowane zwykłe elementy archiwum; przejścia ścieżek, dowiązania i niebezpieczne typy są odrzucane bez ogólnego wypakowywania.'),
        text('Nominal policy includes 512 MiB collection download/bundle budgets, 128 MiB per expanded archive member, 1 GiB expanded bytes per collection, 10,000 members, compression ratio 500, 256 KiB per physical line, 120 seconds per archive task and two concurrent archive tasks. Effective validated deployment limits apply. Byte, line, count, time, buffer and cancellation limits produce explicit rejected/partial coverage; a truncated line preview cannot establish that a literal term was absent.', 'Nominalna polityka obejmuje 512 MiB pobrania kolekcji/pakietu, 128 MiB na rozwinięty element archiwum, 1 GiB rozwiniętych bajtów na kolekcję, 10 000 elementów, współczynnik kompresji 500, 256 KiB na fizyczny wiersz, 120 sekund na zadanie archiwum i dwa równoległe zadania archiwów. Obowiązują skuteczne zwalidowane limity instalacji. Limity bajtów, wierszy, liczby, czasu, bufora i anulowania dają jawne odrzucenie/częściowe pokrycie; skrócony podgląd wiersza nie dowodzi braku dosłownego warunku.'),
      ] },
      { title: text('Resolve failures safely', 'Bezpieczne rozwiązywanie błędów'), paragraphs: [
        text('Unknown/changed key: stop and have an Administrator verify the fingerprint independently; never disable key checking. Authentication failure: verify the bound credential and expiry. SFTP unavailable: the host operator must enable the intended SFTP subsystem. Permission denied/not found: verify the configured regular path and dedicated account’s read/traversal rights, including rotation permissions. Root denied: correct the configured path/root relationship and obtain the current approval when required.', 'Nieznany/zmieniony klucz: zatrzymaj się i poproś Administratora o niezależne potwierdzenie odcisku; nigdy nie wyłączaj kontroli klucza. Błąd uwierzytelnienia: sprawdź przypisane poświadczenie i ważność. Niedostępne SFTP: operator hosta musi udostępnić właściwy podsystem. Brak uprawnień/pliku: sprawdź skonfigurowaną ścieżkę zwykłego pliku i prawa odczytu/przechodzenia konta, również po rotacji. Odrzucony katalog: popraw relację ścieżka/katalog i uzyskaj bieżące zatwierdzenie, jeśli wymagane.'),
        text('DNS/routing or rejected jump forwarding: check connectivity from the application server and the approved jump route. Parse errors: test the parser against representative original lines; do not substitute receive time. Limit reached: reduce selection or release your unused workspaces/monitors before retrying. Source changed/gap: review partial coverage and repeat an explicit bounded collection if needed. A stale revision requires fresh configuration or import preview; do not force an overwrite.', 'DNS/routing lub odrzucone przekazywanie: sprawdź łączność z serwera aplikacji i zatwierdzoną trasę pośrednią. Błędy parsowania: przetestuj parser na reprezentatywnych oryginalnych wierszach; nie podstawiaj czasu odbioru. Osiągnięty limit: zmniejsz wybór lub zwolnij swoje nieużywane obszary/monitory przed ponowieniem. Zmiana źródła/luka: przejrzyj częściowe pokrycie i w razie potrzeby jawnie ponów ograniczone zbieranie. Nieaktualna wersja wymaga świeżej konfiguracji lub podglądu importu; nie wymuszaj nadpisania.'),
        text('Database unavailable or schema mismatch: protected actions and streams fail closed; the server operator must restore the configured endpoint/TLS/schema before retrying. No alternate database is silently used. Another owner/System resource returns unavailable; account role restrictions remain enforced even if a URL or ID is known. For interrupted monitors, use explicit resume/start controls; dismissing a reminder only hides that page’s notice.', 'Niedostępna baza lub niezgodny schemat: chronione akcje i strumienie są blokowane; operator serwera musi przywrócić skonfigurowany punkt/TLS/schemat przed ponowieniem. Nie jest po cichu używana inna baza. Zasób innego właściciela/Systemu jest niedostępny; ograniczenia roli obowiązują nawet przy znajomości URL lub ID. Przerwane monitory wznawiaj/uruchamiaj jawnie; odrzucenie przypomnienia ukrywa jedynie komunikat tej strony.'),
      ] },
    ],
  },
];

export function helpText(value: Text, language: Language): string { return value[language]; }

export function matchingHelpChapters(query: string, language: Language): HelpChapter[] {
  const term = query.trim().toLocaleLowerCase(language);
  if (!term) return helpChapters;
  return helpChapters.filter(chapter => [chapter.title[language], ...chapter.sections.flatMap(section => [section.title[language], ...section.paragraphs.map(paragraph => paragraph[language]), ...(section.operations?.flatMap(operation => [operation.name, operation.description[language]]) ?? [])])].some(value => value.toLocaleLowerCase(language).includes(term)));
}
